// src/pages/Resources.js
import React from "react";
import { useNavigate, useParams } from "react-router-dom";

const naturalSciences = [
  { id: "biology", name: "Biology" },
  { id: "chemistry", name: "Chemistry" },
  { id: "physics", name: "Physics" },
];

const socialSciences = [
  { id: "psychology", name: "Psychology" },
  { id: "sociology", name: "Sociology" },
  { id: "economics", name: "Economics" },
];

function Resources() {
  const navigate = useNavigate();
  const params = useParams();
  const branchParam = params.branch; // optional /resources/:branch

  function handleOpenScience(scienceId, branch) {
    navigate(`/resources/${branch}/${scienceId}`);
  }

  return (
    <section className="resources-page fade-in">
      <h1>Resources</h1>
      <p className="subtitle">
        Choose Natural Science or Social Science, then pick a science to see videos,
        lessons, quizzes, and public chat.
      </p>

      <div className="resources-branches">
        <div className="card resources-branch">
          <h2>Natural Science</h2>
          <div className="resources-grid">
            {naturalSciences.map((science) => (
              <button
                key={science.id}
                className="science-pill"
                onClick={() => handleOpenScience(science.id, "natural")}
              >
                {science.name}
              </button>
            ))}
          </div>
        </div>

        <div className="card resources-branch">
          <h2>Social Science</h2>
          <div className="resources-grid">
            {socialSciences.map((science) => (
              <button
                key={science.id}
                className="science-pill"
                onClick={() => handleOpenScience(science.id, "social")}
              >
                {science.name}
              </button>
            ))}
          </div>
        </div>
      </div>
    </section>
  );
}

export default Resources;
